if (!Array.isArray(bundle.source_documents) || bundle.source_documents.length !== 3)
    throw new Error('APPLICATION_CONTRACT_BUNDLE_SOURCE_COUNT_MISMATCH');
const paths = bundle.source_documents.map(source => source.path);
if (new Set(paths).size !== paths.length || bundle.source_documents.some(source => !/^config\/(statement-sources|transaction-email-sources|ai-policies)\.json$/.test(source.path) || !/^[a-f0-9]{64}$/.test(source.sha256)))
    throw new Error('APPLICATION_CONTRACT_BUNDLE_SOURCE_HASH_INVALID');
if (!Array.isArray(bundle.resolver_maps) || bundle.resolver_maps.length !== 4 || bundle.resolver_maps.some((resolver, index) => resolver.workflow_code !== bundle.resolver_order[index] || !Array.isArray(resolver.entries) || !resolver.entries.length || !Array.isArray(resolver.sources) || resolver.sources.length !== 1 || new Set(resolver.entries.map(entry => entry.key)).size !== resolver.entries.length || resolver.sources[0].sha256 !== bundle.source_documents.find(source => source.path === resolver.sources[0].path)?.sha256))
    throw new Error('APPLICATION_CONTRACT_BUNDLE_RESOLVER_MAP_INVALID');
return [{ json: { application_contract_bundle: bundle, application_contract_bundle_verified: true, bundle_content_sha256: bundle.bundle_content_sha256 } }];

